import { cva, type VariantProps } from 'class-variance-authority';

/** Variant definitions for the click-to-edit container */
export const clickToEditVariants = cva(
  'group/cte relative rounded-md transition-all duration-200',
  {
    variants: {
      status: {
        default: 'border-transparent',
        success:
          'border border-green-500 ring-1 ring-green-500/20 dark:border-green-400 dark:ring-green-400/20',
        warning:
          'border border-amber-500 ring-1 ring-amber-500/20 dark:border-amber-400 dark:ring-amber-400/20',
        error:
          'border border-destructive ring-1 ring-destructive/20 dark:border-destructive dark:ring-destructive/40',
      },
      size: {
        sm: 'text-xs',
        default: 'text-sm',
        lg: 'text-base',
      },
    },
    defaultVariants: {
      status: 'default',
      size: 'default',
    },
  }
);

export type ClickToEditVariants = VariantProps<typeof clickToEditVariants>;

/** Size-specific layout (padding + gap) for display mode */
export const sizeLayout = {
  sm: 'gap-1 py-0.5 px-0.5',
  default: 'gap-1.5 py-1 px-1',
  lg: 'gap-2 py-1.5 px-1.5',
} as const;

/** Size-specific icon dimensions */
export const sizeIcon = {
  sm: 'h-3 w-3',
  default: 'h-3.5 w-3.5',
  lg: 'h-4 w-4',
} as const;

/** Size-specific action button dimensions */
export const sizeActionBtn = {
  sm: 'h-5 w-5',
  default: 'h-6 w-6',
  lg: 'h-7 w-7',
} as const;

/** Status message color mapping */
export const statusMessageColors = {
  default: 'text-muted-foreground',
  success: 'text-green-600 dark:text-green-400',
  warning: 'text-amber-600 dark:text-amber-400',
  error: 'text-destructive dark:text-red-400',
} as const;

import { type ReactNode, useCallback, useEffect, useRef, useState } from 'react';

import { Check, Pencil, X } from 'lucide-react';

import { cn } from '../../../lib/utils';
import {
  type ClickToEditVariants,
  clickToEditVariants,
  sizeActionBtn,
  sizeIcon,
  sizeLayout,
  statusMessageColors,
} from './click-to-edit-variants';

export interface ClickToEditProps extends ClickToEditVariants {
  /** Content displayed in view mode */
  children: ReactNode;
  /** Render function for edit mode — receives confirm/cancel callbacks */
  renderEditor: (props: { onConfirm: () => void; onCancel: () => void }) => ReactNode;
  /** Status feedback variant */
  status?: 'default' | 'success' | 'warning' | 'error';
  /** Optional message displayed below the component */
  statusMessage?: string;
  /** Disable editing */
  disabled?: boolean;
  /** Controlled editing state */
  isEditing?: boolean;
  /** Initial editing state (uncontrolled) */
  defaultEditing?: boolean;
  /** Called when entering edit mode */
  onEditStart?: () => void;
  /** Called when user confirms edit */
  onConfirm?: () => void;
  /** Called when user cancels edit */
  onCancel?: () => void;
  /** Show pencil icon on hover (default: true) */
  showEditIcon?: boolean;
  /** Show confirm/cancel action buttons in edit mode (default: true) */
  showActions?: boolean;
  /** Click anywhere on display to enter edit mode (default: true) */
  editOnClick?: boolean;
  /** Additional class for the outer container */
  className?: string;
}

export function ClickToEdit({
  children,
  renderEditor,
  status = 'default',
  statusMessage,
  disabled = false,
  isEditing: controlledIsEditing,
  defaultEditing = false,
  onEditStart,
  onConfirm,
  onCancel,
  size: sizeProp = 'default',
  showEditIcon = true,
  showActions = true,
  editOnClick = true,
  className,
}: ClickToEditProps) {
  const size = sizeProp ?? 'default';
  const isControlled = controlledIsEditing !== undefined;
  const [internalEditing, setInternalEditing] = useState(defaultEditing);
  const editing = isControlled ? controlledIsEditing : internalEditing;
  const containerRef = useRef<HTMLDivElement>(null);

  const startEditing = useCallback(() => {
    if (disabled) return;
    if (!isControlled) setInternalEditing(true);
    onEditStart?.();
  }, [disabled, isControlled, onEditStart]);

  const handleConfirm = useCallback(() => {
    if (!isControlled) setInternalEditing(false);
    onConfirm?.();
  }, [isControlled, onConfirm]);

  const handleCancel = useCallback(() => {
    if (!isControlled) setInternalEditing(false);
    onCancel?.();
  }, [isControlled, onCancel]);

  /** Close on Escape key when in edit mode */
  useEffect(() => {
    if (!editing) return;
    const handleKeyDown = (e: KeyboardEvent) => {
      if (e.key === 'Escape') {
        e.preventDefault();
        handleCancel();
      }
    };
    const container = containerRef.current;
    container?.addEventListener('keydown', handleKeyDown);
    return () => container?.removeEventListener('keydown', handleKeyDown);
  }, [editing, handleCancel]);

  return (
    <div className="inline-flex w-full flex-col">
      <div
        ref={containerRef}
        className={cn(
          clickToEditVariants({ status, size }),
          disabled && 'pointer-events-none opacity-50',
          className
        )}
      >
        {editing ? (
          /* ── Edit Mode: editor renders directly, no extra padding ── */
          <div className="flex items-center gap-1">
            <div className="min-w-0 flex-1">
              {renderEditor({ onConfirm: handleConfirm, onCancel: handleCancel })}
            </div>
            {showActions && (
              <div className="flex shrink-0 items-center gap-0.5">
                <button
                  type="button"
                  onClick={handleConfirm}
                  className={cn(
                    'inline-flex items-center justify-center rounded text-green-600 hover:bg-green-100 dark:text-green-400 dark:hover:bg-green-900/30',
                    sizeActionBtn[size]
                  )}
                  aria-label="Confirm"
                >
                  <Check className={sizeIcon[size]} />
                </button>
                <button
                  type="button"
                  onClick={handleCancel}
                  className={cn(
                    'inline-flex items-center justify-center rounded text-red-600 hover:bg-red-100 dark:text-red-400 dark:hover:bg-red-900/30',
                    sizeActionBtn[size]
                  )}
                  aria-label="Cancel"
                >
                  <X className={sizeIcon[size]} />
                </button>
              </div>
            )}
          </div>
        ) : (
          /* ── Display Mode: clean, borderless, hover reveals edit icon ── */
          <div
            className={cn(
              'flex items-center rounded-md transition-colors',
              sizeLayout[size],
              !disabled && editOnClick && 'cursor-pointer hover:bg-accent/50'
            )}
            onClick={editOnClick ? startEditing : undefined}
            onKeyDown={
              editOnClick
                ? (e) => {
                    if (e.key === 'Enter' || e.key === ' ') {
                      e.preventDefault();
                      startEditing();
                    }
                  }
                : undefined
            }
            role="button"
            tabIndex={editOnClick && !disabled ? 0 : undefined}
          >
            <div className="min-w-0 flex-1">{children}</div>
            {showEditIcon && !disabled && (
              <span
                className={cn(
                  'inline-flex shrink-0 items-center justify-center text-muted-foreground transition-colors group-hover/cte:text-foreground',
                  sizeActionBtn[size]
                )}
                aria-hidden="true"
              >
                <Pencil className={sizeIcon[size]} />
              </span>
            )}
          </div>
        )}
      </div>

      {/* ── Status Message ── */}
      {statusMessage && (
        <p
          className={cn(
            'mt-1',
            size === 'sm' ? 'text-[10px]' : size === 'lg' ? 'text-sm' : 'text-xs',
            statusMessageColors[status ?? 'default']
          )}
        >
          {statusMessage}
        </p>
      )}
    </div>
  );
}
